/**
 * Integration tests for forEach metadata extraction
 *
 * These tests verify that when building flows with forEach loops over action outputs,
 * the label cache contains correct metadata (parent_table_name, columnName, reference).
 */

import { path } from '@servicenow/sdk-build-core'
import { getMergedRecordUpdates } from '../test-utils'
import { createTestContext } from '../../../test-utils'

describe('ForEach Metadata Extraction - Label Cache Tests', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    /**
     * Helper to find forEach item property pills in label cache
     * Pills are stored as "<UUID>.item.<property>" (e.g., "<UUID>.item.asset_tag")
     */
    function findForEachItemPropertyPills(labelCache: any[]): any[] {
        return labelCache.filter((pill: any) => {
            // forEach item property pills have names like "<UUID>.item.<property>"
            return pill.name && /^[a-f0-9-]{36}\.item\./i.test(pill.name)
        })
    }

    /**
     * Helper to parse metadata from pill name
     * Format: <UUID>.item.<property>|type|meta:parentTable:columnName:reference
     */
    function parseMetadata(pillName: string): {
        uuidPrefix: string
        itemPath: string
        property: string
        type: string | null
        parentTable: string | null
        columnName: string | null
        reference: string | null
    } {
        const parts = pillName.split('|')
        const pathPart = parts[0] // e.g., "<UUID>.item.asset_tag"
        const pathSegments = pathPart.split('.')
        const uuidPrefix = pathSegments[0]
        const itemPath = pathSegments[1] || ''
        const property = pathSegments.slice(2).join('.') || ''
        const type = parts[1] || null
        const metaPart = parts.find((p) => p.startsWith('meta:'))

        if (!metaPart) {
            return { uuidPrefix, itemPath, property, type, parentTable: null, columnName: null, reference: null }
        }

        // meta:parentTable:columnName:reference
        const metaValues = metaPart.replace('meta:', '').split(':')
        return {
            uuidPrefix,
            itemPath,
            property,
            type,
            parentTable: metaValues[0] || null,
            columnName: metaValues[1] || null,
            reference: metaValues[2] || null,
        }
    }

    describe('Pattern A: OutputsWithDependentTable (lookUpRecords)', () => {
        it('should extract reference="alm_hardware" from lookUpRecords action output', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-lookup-records.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            expect(flowRecord).toBeDefined()
            expect(flowRecord.label_cache).toBeDefined()

            const labelCache = JSON.parse(flowRecord.label_cache)
            expect(Array.isArray(labelCache)).toBe(true)
            expect(labelCache.length).toBeGreaterThan(0)

            // Find forEach item property pills
            const forEachPills = findForEachItemPropertyPills(labelCache)

            expect(forEachPills.length).toBeGreaterThan(0)

            // Check if metadata is present (if my implementation is working)
            const firstPill = forEachPills[0]
            if (firstPill.name.includes('|meta:')) {
                const metadata = parseMetadata(firstPill.name)
                expect(metadata.columnName).toBe('Records')
                expect(metadata.reference).toBe('alm_hardware')
            }
        })
    })

    describe('Nested ForEach with Multiple Tables', () => {
        it('should extract correct references for nested forEach loops', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-nested-lookups.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)

            const forEachPills = findForEachItemPropertyPills(labelCache)
            expect(forEachPills.length).toBeGreaterThan(0)

            // Group pills by forEach loop UUID
            const pillsByUUID = new Map<string, any[]>()
            forEachPills.forEach((pill: any) => {
                const uuid = pill.name.split('.')[0]
                if (!pillsByUUID.has(uuid)) {
                    pillsByUUID.set(uuid, [])
                }
                pillsByUUID.get(uuid)!.push(pill)
            })

            // We should have at least 2 distinct forEach loops
            expect(pillsByUUID.size).toBeGreaterThanOrEqual(2)

            // Check metadata if present
            const pillsWithMeta = forEachPills.filter((p: any) => p.name.includes('|meta:'))
            if (pillsWithMeta.length > 0) {
                const metadataList = pillsWithMeta.map((pill: any) => parseMetadata(pill.name))
                const references = metadataList.map((m: any) => m.reference).filter(Boolean)
                expect(references.length).toBeGreaterThan(0)
            }
        })
    })

    describe('Multiple Different Tables', () => {
        it('should extract correct reference for multiple tables', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-multiple-tables.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)

            const forEachPills = findForEachItemPropertyPills(labelCache)
            expect(forEachPills.length).toBeGreaterThan(0)

            // Group pills by forEach loop UUID
            const pillsByUUID = new Map<string, any[]>()
            forEachPills.forEach((pill: any) => {
                const uuid = pill.name.split('.')[0]
                if (!pillsByUUID.has(uuid)) {
                    pillsByUUID.set(uuid, [])
                }
                pillsByUUID.get(uuid)!.push(pill)
            })

            // Should have 3 forEach loops
            expect(pillsByUUID.size).toBeGreaterThanOrEqual(3)
        })
    })

    describe('Flow Logic Instance Validation', () => {
        it('should create correct flow_logic_instance_v2 records for forEach', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-lookup-records.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances).toBeDefined()
            expect(Array.isArray(flowLogicInstances)).toBe(true)

            // Find forEach logic instances (top-level instances without parent)
            const forEachInstances = flowLogicInstances.filter((logic: any) => logic.ui_id && !logic.parent_ui_id)

            expect(forEachInstances.length).toBeGreaterThan(0)

            // Verify each forEach has required fields
            forEachInstances.forEach((forEachLogic: any) => {
                expect(forEachLogic).toHaveProperty('ui_id')
                expect(forEachLogic).toHaveProperty('values')
                expect(forEachLogic).toHaveProperty('logic_definition')
            })
        })
    })

    describe('Label Cache Structure', () => {
        it('should have valid label cache with forEach pills', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-lookup-records.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)

            // Verify label cache is valid
            expect(Array.isArray(labelCache)).toBe(true)
            expect(labelCache.length).toBeGreaterThan(0)

            // Verify each pill has required fields
            labelCache.forEach((pill: any) => {
                expect(pill).toHaveProperty('name')
                expect(pill).toHaveProperty('label')
                expect(pill).toHaveProperty('type')
                expect(pill).toHaveProperty('usedInstances')
            })

            // Verify forEach pills exist
            const forEachPills = findForEachItemPropertyPills(labelCache)
            expect(forEachPills.length).toBeGreaterThan(0)
        })
    })

    describe('ForEach Metadata - Label Cache Format', () => {
        it('should include metadata in forEach item pill names', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-lookup-records.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)
            const forEachPills = findForEachItemPropertyPills(labelCache)

            expect(forEachPills.length).toBeGreaterThan(0)

            // Verify forEach pills have proper structure
            forEachPills.forEach((pill: any) => {
                // Each pill should have UUID.item.property format
                expect(pill.name).toMatch(/^[a-f0-9-]{36}\.item\.\w+/)

                // Each pill should have type and base_type
                expect(pill).toHaveProperty('type')
                expect(pill).toHaveProperty('base_type')
                expect(pill.type).toBeTruthy()
                expect(pill.base_type).toBeTruthy()

                // Each pill should have usedInstances tracking
                expect(pill.usedInstances).toBeDefined()
                expect(Object.keys(pill.usedInstances).length).toBeGreaterThan(0)

                // If metadata is present, verify format
                if (pill.name.includes('|meta:')) {
                    const metadata = parseMetadata(pill.name)
                    expect(metadata).toHaveProperty('columnName')
                    expect(metadata).toHaveProperty('reference')
                    expect(metadata).toHaveProperty('parentTable')
                }
            })
        })

        it('should generate correct labels for forEach item properties', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-lookup-records.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)
            const forEachPills = findForEachItemPropertyPills(labelCache)

            // Verify labels follow forEach pattern
            forEachPills.forEach((pill: any) => {
                expect(pill.label).toContain('For Each')
                expect(pill.label).toContain('➛')
                // Label format: "N - For Each - ➛item➛Property Name"
                expect(pill.label).toMatch(/\d+\s*-\s*For Each.*➛.*➛/)
            })
        })

        it('should deduplicate forEach item pills across multiple usages', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-lookup-records.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)

            // Group pills by name to check for duplicates
            const pillsByName = new Map<string, any[]>()
            labelCache.forEach((pill: any) => {
                if (!pillsByName.has(pill.name)) {
                    pillsByName.set(pill.name, [])
                }
                pillsByName.get(pill.name)!.push(pill)
            })

            // Verify no duplicate pill names
            pillsByName.forEach((pills) => {
                expect(pills.length).toBe(1)
            })

            // Verify forEach pills track all their usages
            const forEachPills = findForEachItemPropertyPills(labelCache)
            forEachPills.forEach((pill: any) => {
                expect(Object.keys(pill.usedInstances).length).toBeGreaterThan(0)
            })
        })
    })

    describe('ForEach Metadata - Reference Table Extraction', () => {
        it('should extract reference table from lookUpRecords action output', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-lookup-records.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)
            const forEachPills = findForEachItemPropertyPills(labelCache)

            // Find pills with metadata
            const pillsWithMeta = forEachPills.filter((p: any) => p.name.includes('|meta:'))

            if (pillsWithMeta.length > 0) {
                pillsWithMeta.forEach((pill: any) => {
                    const metadata = parseMetadata(pill.name)

                    // Verify reference table is alm_hardware
                    expect(metadata.reference).toBe('alm_hardware')

                    // Verify columnName is Records (from action output)
                    expect(metadata.columnName).toBe('Records')

                    // Verify itemPath is 'item'
                    expect(metadata.itemPath).toBe('item')
                })
            }
        })

        it('should extract different reference tables for nested forEach loops', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-nested-lookups.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)
            const forEachPills = findForEachItemPropertyPills(labelCache)

            // Group by forEach UUID to identify different loops
            const pillsByUUID = new Map<string, any[]>()
            forEachPills.forEach((pill: any) => {
                const uuid = pill.name.split('.')[0]
                if (!pillsByUUID.has(uuid)) {
                    pillsByUUID.set(uuid, [])
                }
                pillsByUUID.get(uuid)!.push(pill)
            })

            // Should have at least 2 forEach loops
            expect(pillsByUUID.size).toBeGreaterThanOrEqual(2)

            // Check metadata for pills that have it
            const pillsWithMeta = forEachPills.filter((p: any) => p.name.includes('|meta:'))
            if (pillsWithMeta.length > 0) {
                const metadataList = pillsWithMeta.map((p: any) => parseMetadata(p.name))
                const references = [...new Set(metadataList.map((m: any) => m.reference).filter(Boolean))]

                // Should have references to different tables
                expect(references.length).toBeGreaterThan(0)
            }
        })

        it('should handle multiple forEach loops with different table types', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-multiple-tables.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)
            const forEachPills = findForEachItemPropertyPills(labelCache)

            // Group pills by forEach loop UUID
            const pillsByUUID = new Map<string, any[]>()
            forEachPills.forEach((pill: any) => {
                const uuid = pill.name.split('.')[0]
                if (!pillsByUUID.has(uuid)) {
                    pillsByUUID.set(uuid, [])
                }
                pillsByUUID.get(uuid)!.push(pill)
            })

            // Should have 3 different forEach loops
            expect(pillsByUUID.size).toBeGreaterThanOrEqual(3)

            // Check metadata if present
            const pillsWithMeta = forEachPills.filter((p: any) => p.name.includes('|meta:'))
            if (pillsWithMeta.length > 0) {
                // Verify each forEach loop has its own reference table
                const metadataByUUID = new Map<string, any>()
                pillsWithMeta.forEach((pill: any) => {
                    const uuid = pill.name.split('.')[0]
                    if (!metadataByUUID.has(uuid)) {
                        metadataByUUID.set(uuid, parseMetadata(pill.name))
                    }
                })

                // Each forEach should have a reference
                metadataByUUID.forEach((metadata) => {
                    expect(metadata.reference).toBeTruthy()
                    expect(metadata.columnName).toBe('Records')
                })
            }
        })
    })

    describe('ForEach Metadata - Type and Base Type', () => {
        it('should include correct type information for forEach item properties', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-lookup-records.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)
            const forEachPills = findForEachItemPropertyPills(labelCache)

            // Verify all forEach pills have type and base_type
            forEachPills.forEach((pill: any) => {
                expect(pill).toHaveProperty('type')
                expect(pill).toHaveProperty('base_type')
                expect(pill.type).toBeTruthy()
                expect(pill.base_type).toBeTruthy()

                // Type should not be empty
                expect(pill.type).not.toBe('')
                expect(pill.base_type).not.toBe('')
            })
        })

        it('should maintain type consistency across forEach item property accesses', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-nested-lookups.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)
            const forEachPills = findForEachItemPropertyPills(labelCache)

            // Verify type information is present and consistent
            forEachPills.forEach((pill: any) => {
                expect(pill.type).toBeTruthy()
                expect(pill.base_type).toBeTruthy()

                // Type and base_type should be strings
                expect(typeof pill.type).toBe('string')
                expect(typeof pill.base_type).toBe('string')
            })
        })
    })

    describe('ForEach Metadata - Instance Tracking', () => {
        it('should track all instances where forEach item properties are used', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-lookup-records.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)
            const forEachPills = findForEachItemPropertyPills(labelCache)

            // Verify usedInstances tracking
            forEachPills.forEach((pill: any) => {
                expect(pill.usedInstances).toBeDefined()
                expect(typeof pill.usedInstances).toBe('object')
                expect(Object.keys(pill.usedInstances).length).toBeGreaterThan(0)

                // Each instance should have an ID
                Object.keys(pill.usedInstances).forEach((instanceId) => {
                    expect(instanceId).toBeTruthy()
                    expect(typeof instanceId).toBe('string')
                })
            })
        })

        it('should not duplicate pills in label cache', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-multiple-tables.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)

            // Build a map of pill names to count occurrences
            const pillCounts = new Map<string, number>()
            labelCache.forEach((pill: any) => {
                const count = pillCounts.get(pill.name) || 0
                pillCounts.set(pill.name, count + 1)
            })

            // Verify no pill name appears more than once
            pillCounts.forEach((count) => {
                expect(count).toBe(1)
            })
        })
    })

    describe('ForEach Metadata - Glide List Type', () => {
        it('should extract metadata from glide_list type trigger fields', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-metadata-glide-list.now.ts',
                'flow-logics/fluent'
            )

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)

            // Find the trigger field pill (Created_1.current.type)
            const triggerFieldPill = labelCache.find(
                (pill: any) => pill.name && pill.name.includes('Created_1.current.additional_assignee_list')
            )

            expect(triggerFieldPill).toBeDefined()

            // Verify glide_list metadata attributes are populated exactly
            expect(triggerFieldPill.parent_table_name).toBe('incident')
            expect(triggerFieldPill.column_name).toBe('additional_assignee_list')
            expect(triggerFieldPill.reference).toBe('sys_user')
        })
    })
})
